/**
 * A `private` project is visible only to admins/owners, platform staff, its
 * lead and its explicit project members. `org` and `public` are unaffected.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (project.visibility !== "private") return true;
  if (actor.orgId !== project.orgId) return false;
  if (actor.isPlatformStaff === true) return true;
  if (actor.role === "admin" || actor.role === "owner") return true;
  if (project.leadId !== null && project.leadId === actor.userId) return true;
  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

/** Throws `NotFoundError` so a hidden project is indistinguishable from none. */
export async function assertProjectVisible(
  actor: Actor,
  project: Project,
  lookupKey: string = project.id,
): Promise<void> {
  if (!(await canViewProject(actor, project))) {
    throw new NotFoundError("Project", lookupKey);
  }
}

/** Loads the project by id and asserts the actor may see it. */
export async function assertProjectIdVisible(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  await assertProjectVisible(actor, project);
  return project;
}

/** Ids of the org's private projects the actor may not see. */
export async function hiddenProjectIds(
  actor: Actor,
): Promise<readonly ProjectId[]> {
  if (actor.isPlatformStaff === true) return [];
  if (actor.role === "admin" || actor.role === "owner") return [];
  const privates = await projectRepo.listPrivateProjects(actor.orgId);
  const hidden: ProjectId[] = [];
  for (const project of privates) {
    if (!(await canViewProject(actor, project))) hidden.push(project.id);
  }
  return hidden;
}
