/**
 * A `private` project is visible only to admins/owners, platform staff, its
 * lead and its explicit project members. `org` and `public` are unaffected.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (project.visibility !== "private") return true;
  if (actor.orgId !== project.orgId) return false;
  if (actor.isPlatformStaff === true) return true;
  if (actor.role === "admin" || actor.role === "owner") return true;
  if (project.leadId !== null && project.leadId === actor.userId) return true;
  return projectMemberRepo.isProjectMember(
