    "Project",
    projectId,
  );
  await assertProjectVisible(actor, project);
  return project;
}

/** Ids of the org's private projects the actor may not see. */
export async function hiddenProjectIds(
  actor: Actor,
): Promise<readonly ProjectId[]> {
  if (actor.isPlatformStaff === true) return [];
  if (actor.role === "admin" || actor.role === "owner") return [];
  const privates = await projectRepo.listPrivateProjects(actor.orgId);
